-- Stage 1 DRAFT schema (design artefact, validated against PostgreSQL 16).
-- In Stage 2 it becomes Alembic migrations. Conventions:
--   * ids: UUID (v7, generated by the app). Money NUMERIC(18,4); unit cost NUMERIC(20,8);
--     quantities NUMERIC(18,6) in the ingredient base unit (g | ml | unit).
--   * every branch-owned row has branch_id; transactional rows are append-only.

CREATE TYPE dimension        AS ENUM ('mass', 'volume', 'count');
CREATE TYPE posting_status   AS ENUM ('draft', 'confirmed', 'voided');
CREATE TYPE payment_status   AS ENUM ('unpaid', 'partially_paid', 'paid');
CREATE TYPE movement_type    AS ENUM ('receipt', 'consumption', 'production_issue', 'adjustment',
                                      'count_adjustment', 'reversal', 'transfer_out', 'transfer_in');
CREATE TYPE adjustment_reason AS ENUM ('spoilage', 'expired', 'damaged', 'prep_waste',
                                       'staff_meal', 'count_variance', 'other');
CREATE TYPE recipe_status    AS ENUM ('draft', 'approved', 'published', 'retired');
CREATE TYPE quantity_basis   AS ENUM ('gross', 'net');

-- ───────────────────────────── platform ─────────────────────────────
CREATE TABLE branch (
  id UUID PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
  country CHAR(2) NOT NULL, currency CHAR(3) NOT NULL, timezone TEXT NOT NULL,
  settings JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE device (
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch, name TEXT NOT NULL,
  registered_at TIMESTAMPTZ NOT NULL DEFAULT now(), revoked_at TIMESTAMPTZ
);
CREATE TABLE app_user (
  id UUID PRIMARY KEY, email CITEXT UNIQUE, display_name TEXT NOT NULL,
  password_hash TEXT NOT NULL, pin_hash TEXT, mfa_secret_enc BYTEA,
  is_active BOOLEAN NOT NULL DEFAULT true, failed_logins INT NOT NULL DEFAULT 0,
  locked_until TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE role (id TEXT PRIMARY KEY, description TEXT NOT NULL);
CREATE TABLE role_permission (role_id TEXT REFERENCES role, permission TEXT NOT NULL,
  PRIMARY KEY (role_id, permission));
CREATE TABLE user_branch_role (
  user_id UUID REFERENCES app_user, branch_id UUID REFERENCES branch, role_id TEXT REFERENCES role,
  PRIMARY KEY (user_id, branch_id, role_id)
);
CREATE TABLE idempotency_record (
  branch_id UUID NOT NULL REFERENCES branch, key TEXT NOT NULL, operation TEXT NOT NULL,
  request_hash TEXT NOT NULL, response JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (branch_id, key)
);
CREATE TABLE audit_log (
  id UUID PRIMARY KEY, branch_id UUID REFERENCES branch, user_id UUID REFERENCES app_user,
  device_id UUID REFERENCES device, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id UUID,
  before JSONB, after JSONB, at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON audit_log (branch_id, entity, entity_id);
CREATE TABLE outbox_event (
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch, branch_sequence BIGINT NOT NULL,
  topic TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  attempts INT NOT NULL DEFAULT 0, next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  acked_at TIMESTAMPTZ, ack_signature TEXT,
  UNIQUE (branch_id, branch_sequence)
);
CREATE INDEX outbox_pending ON outbox_event (next_attempt_at) WHERE acked_at IS NULL;
CREATE TABLE inbox_event (
  source TEXT NOT NULL, event_id UUID NOT NULL, topic TEXT NOT NULL, payload JSONB NOT NULL,
  received_at TIMESTAMPTZ NOT NULL DEFAULT now(), processed_at TIMESTAMPTZ, error TEXT,
  PRIMARY KEY (source, event_id)
);
CREATE TABLE sync_conflict (
  id UUID PRIMARY KEY, entity TEXT NOT NULL, entity_id UUID NOT NULL, base_version INT NOT NULL,
  local_payload JSONB NOT NULL, remote_payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'open',
  resolved_by UUID REFERENCES app_user, resolved_at TIMESTAMPTZ
);
CREATE TABLE stored_file (
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch, sha256 CHAR(64) NOT NULL,
  mime_type TEXT NOT NULL, size_bytes BIGINT NOT NULL CHECK (size_bytes > 0),
  storage_key TEXT NOT NULL UNIQUE, uploaded_by UUID REFERENCES app_user,
  uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ───────────────────────── M1 ingredients & recipes ─────────────────────────
CREATE TABLE ingredient_category (id UUID PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE ingredient (
  id UUID PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
  category_id UUID REFERENCES ingredient_category, description TEXT,
  base_dimension dimension NOT NULL, default_purchase_unit TEXT NOT NULL,
  default_consumption_unit TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true,
  is_stock_tracked BOOLEAN NOT NULL DEFAULT true, version INT NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ingredient_name_trgm ON ingredient USING gin (name gin_trgm_ops);
CREATE TABLE ingredient_conversion (          -- ingredient-specific cross-dimension rule
  id UUID PRIMARY KEY, ingredient_id UUID NOT NULL REFERENCES ingredient,
  from_unit TEXT NOT NULL, from_qty NUMERIC(18,6) NOT NULL CHECK (from_qty > 0),
  to_unit TEXT NOT NULL, to_qty NUMERIC(18,6) NOT NULL CHECK (to_qty > 0),
  note TEXT, UNIQUE (ingredient_id, from_unit, to_unit)
);
CREATE TABLE ingredient_branch_setting (
  ingredient_id UUID REFERENCES ingredient, branch_id UUID REFERENCES branch,
  min_stock_base NUMERIC(18,6) NOT NULL DEFAULT 0 CHECK (min_stock_base >= 0),
  stock_policy TEXT NOT NULL DEFAULT 'block', PRIMARY KEY (ingredient_id, branch_id)
);
CREATE TABLE ingredient_current_cost (        -- CURRENT cost basis (ADR-0006)
  ingredient_id UUID REFERENCES ingredient, branch_id UUID REFERENCES branch,
  cost_per_base_unit NUMERIC(20,8) NOT NULL CHECK (cost_per_base_unit >= 0),
  currency CHAR(3) NOT NULL, source_purchase_line_id UUID, updated_at TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (ingredient_id, branch_id)
);
CREATE TABLE ingredient_price_history (       -- append-only
  id UUID PRIMARY KEY, ingredient_id UUID NOT NULL REFERENCES ingredient,
  branch_id UUID NOT NULL REFERENCES branch, supplier_id UUID NOT NULL,
  purchase_line_id UUID NOT NULL, effective_at TIMESTAMPTZ NOT NULL,
  cost_per_base_unit NUMERIC(20,8) NOT NULL, currency CHAR(3) NOT NULL,
  previous_cost_per_base_unit NUMERIC(20,8)
);
CREATE INDEX ON ingredient_price_history (ingredient_id, branch_id, effective_at DESC);

CREATE TABLE recipe (
  id UUID PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
  is_sub_recipe BOOLEAN NOT NULL DEFAULT false, version INT NOT NULL DEFAULT 1
);
CREATE TABLE recipe_version (                 -- immutable once approved
  id UUID PRIMARY KEY, recipe_id UUID NOT NULL REFERENCES recipe, version_no INT NOT NULL,
  status recipe_status NOT NULL DEFAULT 'draft',
  batch_output_qty NUMERIC(18,6) NOT NULL CHECK (batch_output_qty > 0),
  batch_output_unit TEXT NOT NULL, portions_per_batch NUMERIC(18,6) NOT NULL CHECK (portions_per_batch > 0),
  portion_size_qty NUMERIC(18,6), portion_size_unit TEXT,
  cooking_shrinkage_rate NUMERIC(7,6) NOT NULL DEFAULT 0 CHECK (cooking_shrinkage_rate >= 0 AND cooking_shrinkage_rate < 1),
  target_food_cost_rate NUMERIC(7,6) NOT NULL CHECK (target_food_cost_rate > 0 AND target_food_cost_rate < 1),
  selling_price NUMERIC(18,4), currency CHAR(3),
  prep_instructions TEXT, cooking_instructions TEXT,
  created_by UUID REFERENCES app_user, approved_by UUID REFERENCES app_user,
  approved_at TIMESTAMPTZ, published_at TIMESTAMPTZ,
  UNIQUE (recipe_id, version_no)
);
CREATE UNIQUE INDEX one_published_version ON recipe_version (recipe_id) WHERE status = 'published';
CREATE TABLE recipe_line (
  id UUID PRIMARY KEY, recipe_version_id UUID NOT NULL REFERENCES recipe_version,
  ingredient_id UUID REFERENCES ingredient, sub_recipe_id UUID REFERENCES recipe,
  quantity NUMERIC(18,6) NOT NULL CHECK (quantity > 0), unit TEXT NOT NULL,
  basis quantity_basis NOT NULL DEFAULT 'gross',
  prep_loss_rate NUMERIC(7,6) NOT NULL DEFAULT 0 CHECK (prep_loss_rate >= 0 AND prep_loss_rate < 1),
  sort_order INT NOT NULL DEFAULT 0,
  CHECK ((ingredient_id IS NULL) <> (sub_recipe_id IS NULL))
);
CREATE TABLE recipe_cost_snapshot (           -- CURRENT-basis projection history
  id UUID PRIMARY KEY, recipe_version_id UUID NOT NULL REFERENCES recipe_version,
  branch_id UUID NOT NULL REFERENCES branch, computed_at TIMESTAMPTZ NOT NULL,
  trigger TEXT NOT NULL, batch_cost NUMERIC(18,4) NOT NULL, cost_per_portion NUMERIC(18,4) NOT NULL,
  recommended_price NUMERIC(18,4) NOT NULL, food_cost_rate NUMERIC(9,6),
  exceeds_target BOOLEAN NOT NULL, detail JSONB NOT NULL, currency CHAR(3) NOT NULL
);
CREATE INDEX ON recipe_cost_snapshot (recipe_version_id, branch_id, computed_at DESC);

-- ───────────────────────── M2 purchasing & suppliers ─────────────────────────
CREATE TABLE supplier (
  id UUID PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, tax_id TEXT,
  phone TEXT, email TEXT, address TEXT, contact_person TEXT, payment_terms_days INT,
  is_active BOOLEAN NOT NULL DEFAULT true, version INT NOT NULL DEFAULT 1
);
CREATE TABLE supplier_ingredient (
  supplier_id UUID REFERENCES supplier, ingredient_id UUID REFERENCES ingredient,
  supplier_sku TEXT, is_preferred BOOLEAN NOT NULL DEFAULT false,
  PRIMARY KEY (supplier_id, ingredient_id)
);
CREATE TABLE supplier_item_alias (            -- learned OCR matches
  supplier_id UUID REFERENCES supplier, alias_text TEXT NOT NULL,
  ingredient_id UUID NOT NULL REFERENCES ingredient, unit TEXT,
  PRIMARY KEY (supplier_id, alias_text)
);
CREATE TABLE purchase_invoice (
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch,
  supplier_id UUID NOT NULL REFERENCES supplier, invoice_ref TEXT NOT NULL,
  invoice_date DATE NOT NULL, received_at TIMESTAMPTZ NOT NULL, currency CHAR(3) NOT NULL,
  subtotal NUMERIC(18,4) NOT NULL, discount_total NUMERIC(18,4) NOT NULL DEFAULT 0,
  tax_total NUMERIC(18,4) NOT NULL DEFAULT 0, total NUMERIC(18,4) NOT NULL CHECK (total >= 0),
  status posting_status NOT NULL, notes TEXT, attachment_file_id UUID REFERENCES stored_file,
  ocr_draft_id UUID, idempotency_key TEXT NOT NULL,
  confirmed_by UUID REFERENCES app_user, confirmed_at TIMESTAMPTZ,
  origin_device_id UUID REFERENCES device,
  UNIQUE (branch_id, idempotency_key)
);
-- the same supplier invoice cannot be confirmed twice
CREATE UNIQUE INDEX uniq_supplier_invoice ON purchase_invoice (supplier_id, invoice_ref)
  WHERE status = 'confirmed';
CREATE INDEX ON purchase_invoice (branch_id, invoice_date DESC);
CREATE TABLE purchase_line (
  id UUID PRIMARY KEY, invoice_id UUID NOT NULL REFERENCES purchase_invoice,
  line_no INT NOT NULL, ingredient_id UUID REFERENCES ingredient, description TEXT NOT NULL,
  quantity NUMERIC(18,6) NOT NULL CHECK (quantity > 0), unit TEXT NOT NULL,
  unit_price NUMERIC(20,8) NOT NULL CHECK (unit_price >= 0),
  line_discount NUMERIC(18,4) NOT NULL DEFAULT 0, line_total NUMERIC(18,4) NOT NULL,
  base_quantity NUMERIC(18,6), cost_per_base_unit NUMERIC(20,8),
  UNIQUE (invoice_id, line_no)
);
CREATE TABLE purchase_ocr_draft (
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch,
  file_id UUID NOT NULL REFERENCES stored_file, engine TEXT NOT NULL, status TEXT NOT NULL,
  extracted JSONB, reviewed JSONB, created_by UUID REFERENCES app_user,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE supplier_payment (
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch,
  supplier_id UUID NOT NULL REFERENCES supplier, paid_on DATE NOT NULL,
  amount NUMERIC(18,4) NOT NULL CHECK (amount > 0), currency CHAR(3) NOT NULL,
  method TEXT NOT NULL, reference TEXT, status posting_status NOT NULL,
  idempotency_key TEXT NOT NULL, posted_by UUID REFERENCES app_user, posted_at TIMESTAMPTZ,
  UNIQUE (branch_id, idempotency_key)
);
CREATE UNIQUE INDEX uniq_payment_reference ON supplier_payment (supplier_id, method, reference)
  WHERE reference IS NOT NULL AND status = 'confirmed';
CREATE TABLE payment_allocation (
  id UUID PRIMARY KEY, payment_id UUID NOT NULL REFERENCES supplier_payment,
  invoice_id UUID NOT NULL REFERENCES purchase_invoice,
  amount NUMERIC(18,4) NOT NULL CHECK (amount > 0), status posting_status NOT NULL,
  UNIQUE (payment_id, invoice_id)
);
CREATE TABLE supplier_credit (
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch,
  supplier_id UUID NOT NULL REFERENCES supplier, invoice_id UUID REFERENCES purchase_invoice,
  amount NUMERIC(18,4) NOT NULL CHECK (amount > 0), reason TEXT NOT NULL,
  status posting_status NOT NULL, credit_note_ref TEXT
);
CREATE TABLE supplier_ledger_entry (          -- traceable balance: Σ(amount) = payable
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch,
  supplier_id UUID NOT NULL REFERENCES supplier, entry_type TEXT NOT NULL,
  source_id UUID NOT NULL, amount NUMERIC(18,4) NOT NULL, currency CHAR(3) NOT NULL,
  posted_at TIMESTAMPTZ NOT NULL, UNIQUE (entry_type, source_id)
);
CREATE INDEX ON supplier_ledger_entry (supplier_id, branch_id, posted_at);

-- ───────────────────────── M3 inventory (FIFO) ─────────────────────────
CREATE SEQUENCE stock_batch_seq;
CREATE TABLE stock_item (                     -- raw ingredient OR finished good (future)
  id UUID PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('ingredient', 'finished_good')),
  ingredient_id UUID UNIQUE REFERENCES ingredient, recipe_id UUID UNIQUE REFERENCES recipe,
  base_dimension dimension NOT NULL,
  CHECK ((kind = 'ingredient') = (ingredient_id IS NOT NULL))
);
CREATE TABLE stock_batch (
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch,
  stock_item_id UUID NOT NULL REFERENCES stock_item, supplier_id UUID REFERENCES supplier,
  purchase_line_id UUID UNIQUE REFERENCES purchase_line, production_id UUID,
  purchase_date DATE, received_at TIMESTAMPTZ NOT NULL,
  sequence BIGINT NOT NULL DEFAULT nextval('stock_batch_seq'),
  original_quantity NUMERIC(18,6) NOT NULL CHECK (original_quantity > 0),
  remaining_quantity NUMERIC(18,6) NOT NULL,
  unit_cost NUMERIC(20,8) NOT NULL CHECK (unit_cost >= 0), currency CHAR(3) NOT NULL,
  expires_on DATE, is_quarantined BOOLEAN NOT NULL DEFAULT false,
  CHECK (remaining_quantity >= 0 AND remaining_quantity <= original_quantity)
);
CREATE INDEX stock_batch_fifo ON stock_batch (stock_item_id, branch_id, received_at, sequence)
  WHERE remaining_quantity > 0;
CREATE TABLE stock_movement (                 -- immutable header
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch,
  stock_item_id UUID NOT NULL REFERENCES stock_item, type movement_type NOT NULL,
  quantity NUMERIC(18,6) NOT NULL,             -- signed: + in, - out (base units)
  total_cost NUMERIC(18,4) NOT NULL, currency CHAR(3) NOT NULL,
  reason adjustment_reason, note TEXT, source_type TEXT, source_id UUID,
  reverses_movement_id UUID REFERENCES stock_movement, idempotency_key TEXT NOT NULL,
  created_by UUID REFERENCES app_user, device_id UUID REFERENCES device,
  occurred_at TIMESTAMPTZ NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (branch_id, idempotency_key),
  CHECK (type <> 'adjustment' OR reason IS NOT NULL)
);
CREATE INDEX ON stock_movement (stock_item_id, branch_id, occurred_at);
CREATE TABLE stock_allocation (               -- FIFO detail, immutable
  id UUID PRIMARY KEY, movement_id UUID NOT NULL REFERENCES stock_movement,
  batch_id UUID NOT NULL REFERENCES stock_batch,
  quantity NUMERIC(18,6) NOT NULL CHECK (quantity <> 0), unit_cost NUMERIC(20,8) NOT NULL
);
CREATE INDEX ON stock_allocation (batch_id);
CREATE TABLE stock_shortfall (
  id UUID PRIMARY KEY, movement_id UUID NOT NULL REFERENCES stock_movement,
  quantity NUMERIC(18,6) NOT NULL CHECK (quantity > 0), estimated_unit_cost NUMERIC(20,8) NOT NULL,
  approved_by UUID NOT NULL REFERENCES app_user, resolved_at TIMESTAMPTZ, resolution_movement_id UUID
);
CREATE TABLE production_run (                 -- ingredients deducted here, once
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch,
  recipe_version_id UUID NOT NULL REFERENCES recipe_version,
  batches NUMERIC(18,6) NOT NULL CHECK (batches > 0),
  expected_portions NUMERIC(18,6) NOT NULL, actual_portions NUMERIC(18,6),
  actual_output_qty NUMERIC(18,6), status posting_status NOT NULL,
  idempotency_key TEXT NOT NULL, produced_at TIMESTAMPTZ NOT NULL,
  UNIQUE (branch_id, idempotency_key)
);
CREATE TABLE stock_count (
  id UUID PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch, status TEXT NOT NULL,
  started_at TIMESTAMPTZ NOT NULL, approved_by UUID REFERENCES app_user, approved_at TIMESTAMPTZ
);
CREATE TABLE stock_count_line (
  count_id UUID REFERENCES stock_count, stock_item_id UUID REFERENCES stock_item,
  expected_quantity NUMERIC(18,6) NOT NULL, counted_quantity NUMERIC(18,6) NOT NULL CHECK (counted_quantity >= 0),
  counted_by UUID REFERENCES app_user, adjustment_movement_id UUID REFERENCES stock_movement,
  PRIMARY KEY (count_id, stock_item_id)
);
-- future: sales_event (POS) reduces finished_good stock_items, never raw ingredients
-- for items produced in advance; direct-to-order dishes deduct via recipe at sale time.
